// The page book-form: Add a book. It sends its fields to addBook and
// opens book-edit once it succeeds.

import { BOOK_FORM_SUBMITTED, BOOK_FORM_REFUSED } from "./events.js";
import { form } from "./form.js";

form({
  submit: {
    operation: "addBook",
    method: "POST",
    path: () => "/books",
    sent: ["title", "shelf", "authorId", "pages", "lendable", "code", "notes", "boughtOn", "withdrawnOn", "location", "copies"],
    idempotencyKey: "Idempotency-Key",
  },
  checks: [
    { field: "withdrawnOn", rule: (record) => (record.withdrawnOn ?? null) === null || record.withdrawnOn > record.boughtOn, message: "A book is withdrawn after it is bought." },
  ],
  conditions: {
    notes: { readOnlyWhen: (record) => record.shelf === "reference" },
    withdrawnOn: { hiddenWhen: (record) => record.lendable === true },
  },
  pickers: {
    authorId: { path: "/authors", items: "items", pageSize: ["pageSize", 50], search: "search", value: "id", shows: ["name"], fills: {} },
  },
  next: {
    success: { page: "book-edit", with: { bookId: "id" }, message: "The book is added." },
  },
  messages: {
    failed: "This cannot be done right now. Try again in a moment.",
    pattern: "This is not in the form it takes.",
    twice: "The two entries are not the same.",
  },
  // What the operations' refusals say, by status, and the field each is about.
  refusals: {
    submit: {
      "409": { message: "Another book has this title.", field: "title" },
    },
  },
  submitted: BOOK_FORM_SUBMITTED,
  refused: BOOK_FORM_REFUSED,
});
